// Shared by scripts/build-client.mjs and the freshness test.

import { join } from 'node:path';
import { build } from 'esbuild';

export const OUTPUT = 'src/site/client-script.generated.ts';

/** Returns the full text of the generated TypeScript module. */
export async function bundleClient(root) {
  const result = await build({
    entryPoints: [join(root, 'src/client/main.ts')],
    bundle: true,
    format: 'iife',
    target: 'es2020',
    platform: 'browser',
    minify: false,
    legalComments: 'none',
    charset: 'ascii',
    write: false,
    logLevel: 'silent',
  });
  const file = result.outputFiles[0];
  if (!file) throw new Error('esbuild produced no output');
  const code = file.text.trim();
  return [
    '// Copyright 2026 MB AFKzona Group',
    '// SPDX-License-Identifier: AGPL-3.0-only',
    '',
    '// GENERATED by scripts/build-client.mjs from src/client/*.ts. Do not edit.',
    '// Run `npm run build:client` after changing the client code.',
    '',
    '/** The course page script (quiz grading and SCORM 1.2 runtime). */',
    `export const CLIENT_SCRIPT = ${JSON.stringify(code)};`,
    '',
  ].join('\n');
}
